def build_authoring_modules_by_programme(authoring_module_rows):
    modules_by_programme = defaultdict(list)
    seen = defaultdict(set)
    for module in authoring_module_rows or []:
        catalogue_id = clean_str(module.get('module_catalogue_id'))
        for value in (
            module.get('programme_id'),
            module.get('programme_name'),
            f'program-{slugify(module.get("programme_id"))}' if module.get('programme_id') else '',
        ):
            key = authoring_programme_lookup_key(value)
            if key and catalogue_id not in seen[key]:
                modules_by_programme[key].append(module)
                seen[key].add(catalogue_id)
    return modules_by_programme

matching_authoring_module_for_training_r.source:
def matching_authoring_module_for_training_row(row, modules_by_programme, programme_source_id, programme_name):
    meta = row.get('_meta', {})
    lookup_keys = [
        programme_source_id,
        f'program-{slugify(programme_source_id)}' if programme_source_id else '',
        programme_name,
    ]
    candidates = []
    seen = set()
    for value in lookup_keys:
        for module in modules_by_programme.get(authoring_programme_lookup_key(value), []):
            catalogue_id = clean_str(module.get('module_catalogue_id'))
            if catalogue_id and catalogue_id in seen:
                continue
            candidates.append(module)
            if catalogue_id:
                seen.add(catalogue_id)

    if not candidates:
        return None

    training_id = clean_str(row.get('id'))
    catalogue_id = clean_str(meta.get('module_catalogue_id'))
    module_name = normalise(row.get('module_name'))

    exact = next((module for module in candidates if catalogue_id and clean_str(module.get('module_catalogue_id')) == catalogue_id), None)
    if exact:
        return exact

    source_match = next((
        module for module in candidates
        if training_id and clean_str(module.get('source_id')) == training_id
    ), None)
    if source_match:
        return source_match

    title_match = next((module for module in candidates if module_name and normalise(module.get('title')) == module_name), None)
    return title_match or candidates[0]

prefer_authoring_module_sessions.source:
def prefer_authoring_module_sessions(training_sessions, authoring_sessions, authoring_catalogue_ids=None):
    """The Course structure wins for every authoring module, not just the ones it dated.

    ``authoring_catalogue_ids`` is the id of every module the authoring system owns,
    independent of whether it delivered any sessions. Deriving that set from
    ``authoring_sessions`` instead -- as this used to do -- read a module with zero
    authored live sessions as a module the authoring system had no opinion on, so it
    fell through to the legacy generator below, which still invents its sessions from
    ``sessions_number``. A module with no live-session components has to deliver none,
    not the training row's old count.
    """
    if authoring_catalogue_ids is None:
        authoring_catalogue_ids = {
            clean_str(session.get('moduleCatalogueId'))
            for session in authoring_sessions
            if clean_str(session.get('moduleCatalogueId'))
        }
    else:
        authoring_catalogue_ids = {clean_str(value) for value in authoring_catalogue_ids if clean_str(value)}
    filtered_training = [
        session for session in training_sessions
        if clean_str(session.get('moduleCatalogueId')) not in authoring_catalogue_ids
    ]
    return [*authoring_sessions, *filtered_training]

delivery_slots_by_catalogue.source:
def delivery_slots_by_catalogue(
    weeks_by_catalogue, *, modules_by_catalogue=None, groups_by_id=None, holidays_by_cohort=None,
):
    """Each module's planned week slots, for dating its primary live sessions.

    Returns ``{catalogue_id: (slots_by_week, session_plan)}``, the shape
    ``module_week_delivery_slots`` gives. A module whose plan cannot be
    built is simply absent, and its components keep their own stored dates --
    the behaviour the session links had before they read a plan at all.

    Rows a caller already holds are used as given; only what is missing is
    read. ``holidays_by_cohort`` supplied but silent about a cohort means that
    cohort has no ticked holidays, which is how
    ``build_sessions_from_authoring_modules`` reads it too -- passing ``None``
    instead would send the planner to the database for every module.
    """
    catalogue_ids = [clean_str(value) for value in weeks_by_catalogue if clean_str(value)]
    if not catalogue_ids:
        return {}
    modules = {clean_str(key): value for key, value in (modules_by_catalogue or {}).items()}
    missing = [value for value in catalogue_ids if value not in modules]
    if missing:
        try:
            placeholders = ','.join(['%s'] * len(missing))
            for row in authoring_fetch_all(
                AUTHORING_MODULES_TABLE, f'module_catalogue_id in ({placeholders})', missing,
            ):
                modules[clean_str(row.get('module_catalogue_id'))] = row
        except (Exception, AssertionError):
            logger.debug('Unable to read modules for the live-session plan.', exc_info=True)
    groups = {clean_str(key): value for key, value in (groups_by_id or {}).items()}
    if groups_by_id is None:
        wanted = unique([
            clean_str((modules.get(value) or {}).get('group_id')) for value in catalogue_ids
        ])
        wanted = [value for value in wanted if value]
        if wanted:
            try:
                placeholders = ','.join(['%s'] * len(wanted))
                for row in authoring_fetch_all(GROUPS_TABLE, f'group_id in ({placeholders})', wanted):
                    groups[clean_str(row.get('group_id'))] = row
            except (Exception, AssertionError):
                logger.debug('Unable to read groups for the live-session plan.', exc_info=True)
    plans = {}
    for catalogue_id in catalogue_ids:
        module_row = modules.get(catalogue_id)
        week_count = len(weeks_by_catalogue.get(catalogue_id) or [])
        if not module_row or not week_count:
            continue
        holidays = None
        if holidays_by_cohort is not None:
            holidays = holidays_by_cohort.get(clean_str(module_row.get('cohort_id'))) or []
        try:
            plans[catalogue_id] = module_week_delivery_slots(
                module_row,
                groups.get(clean_str(module_row.get('group_id'))) or {},
                week_count,
                holidays=holidays,
            )
        except (Exception, AssertionError):
            # One module's plan failing leaves that module on its stored dates;
            # it must not blank the session links of every other module here.
            logger.debug('Unable to plan live-session dates for %s.', catalogue_id, exc_info=True)
    return plans
